// Seals the verbatim cc-unlock prompt files under src/main/agent/unlock/ into a
// generated TS bundle, so the packaged app carries the exact bytes without
// relying on loose .md files next to the compiled output.
// Regenerate after touching anything under src/main/agent/unlock/:
//   node scripts/build-unlock-bundle.mjs
// test/agent/unlock.test.ts fails when the bundle drifts from the sealed files.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..", "src", "main", "agent", "unlock");
const out = path.resolve(here, "..", "src", "main", "agent", "unlock-bundle.ts");

const read = (rel) => readFileSync(path.join(root, rel), "utf8");
const list = (rel) => readdirSync(path.join(root, rel)).filter((n) => n.endsWith(".md")).sort();

const memory = Object.fromEntries(list("memory").map((n) => [n, read(`memory/${n}`)]));
const skills = Object.fromEntries(list("skills").map((n) => [n, read(`skills/${n}`)]));
const files = ["CLAUDE.md", "system-prompt.md", ...list("memory").map((n) => `memory/${n}`), ...list("skills").map((n) => `skills/${n}`)];

const bundle = `// @generated by scripts/build-unlock-bundle.mjs — do not edit by hand.
// Canonical source: src/main/agent/unlock/*.md (byte-identical to the cc-unlock drop).
/** Sealed file list, relative to src/main/agent/unlock/. */
export const UNLOCK_FILES: readonly string[] = ${JSON.stringify(files, null, 2)};
/** Core module (ZH). */
export const UNLOCK_CORE_ZH: string = ${JSON.stringify(read("CLAUDE.md"))};
/** Core module (EN counterpart). */
export const UNLOCK_CORE_EN: string = ${JSON.stringify(read("system-prompt.md"))};
/** Skill modules, by file name. */
export const UNLOCK_SKILLS: Readonly<Record<string, string>> = ${JSON.stringify(skills)};
/** Memory support files, by file name. Kept sealed for selective loading; not injected by default. */
export const UNLOCK_MEMORY: Readonly<Record<string, string>> = ${JSON.stringify(memory)};
`;

writeFileSync(out, bundle);
console.log(`unlock bundle: ${files.length} files -> ${out} (${Buffer.byteLength(bundle)} bytes)`);
